<?php
require __DIR__.'/../src/bootstrap.php'; $user=requireLogin(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requirePost();try{SupplierService::save($user,$_POST,intField($_POST,'id'));flash('Đã lưu nhà cung cấp.');redirect('/suppliers.php');}catch(DomainException $e){$error=ERROR_LABELS[$e->getMessage()]??'Không lưu được nhà cung cấp. Kiểm tra mã và tên công ty.';}catch(Throwable $e){error_log('Supplier save failed: '.$e->getMessage());$error='Không lưu được nhà cung cấp. Mã có thể đã tồn tại.';}}
$suppliers=Store::all('suppliers');$q=trim(field($_GET,'q'));if($q!=='')$suppliers=array_filter($suppliers,fn($s)=>stripos($s['code'].' '.$s['company_name'].' '.$s['tax_code'].' '.$s['address'],$q)!==false);$editing=isset($_GET['edit'])?Store::find('suppliers',intField($_GET,'edit')??0):null;$title='Nhà cung cấp';$active='suppliers';require __DIR__.'/../templates/header.php';
?>
<header class="page-head"><div><h1>Nhà cung cấp</h1><p>Quản lý nguồn nhập và lịch sử chứng từ theo nhà cung cấp.</p></div></header>
<?php if($error):?><div class="error-summary" role="alert"><?=e($error)?></div><?php endif;?>
<?php if(canManageCatalog($user)):?><section class="card"><h2><?=$editing?'Sửa nhà cung cấp':'Thêm nhà cung cấp'?></h2><form method="post" class="form"><?=csrfInput()?><input type="hidden" name="id" value="<?=e((string)($editing['id']??''))?>"><div class="form-row"><label class="form-field">Mã<input name="code" required maxlength="40" value="<?=e($editing['code']??'')?>"></label><label class="form-field form-field--wide">Tên công ty<input name="company_name" required maxlength="200" value="<?=e($editing['company_name']??'')?>"></label><label class="form-field">Mã số thuế<input name="tax_code" maxlength="40" value="<?=e($editing['tax_code']??'')?>"></label><label class="form-field">Người liên hệ<input name="contact_name" maxlength="160" value="<?=e($editing['contact_name']??'')?>"></label><label class="form-field">Điện thoại<input name="phone" maxlength="40" value="<?=e($editing['phone']??'')?>"></label><label class="form-field">Email<input type="email" name="email" maxlength="160" value="<?=e($editing['email']??'')?>"></label><label class="form-field form-field--wide">Địa chỉ<input name="address" value="<?=e($editing['address']??'')?>"></label><label><input type="checkbox" name="active" <?=!isset($editing['active'])||$editing['active']?'checked':''?>> Đang hoạt động</label></div><button class="button">Lưu</button></form></section><?php endif;?>
<form class="filters" method="get"><label>Tìm kiếm<input name="q" value="<?=e($q)?>" placeholder="Mã, tên, MST hoặc địa chỉ"></label><button class="button">Lọc</button></form>
<section class="card table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Công ty</th><th>Liên hệ</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($suppliers as $s):?><tr><td><?=e($s['code'])?></td><td><strong><?=e($s['company_name'])?></strong><br><span class="muted"><?=e($s['tax_code'])?></span></td><td><?=e($s['contact_name'].' '.$s['phone'])?><br><?=e($s['email'])?></td><td><?= $s['active']?'Đang hoạt động':'Ngừng hoạt động'?></td><td><?php if(canManageCatalog($user)):?><a class="text-link" href="/suppliers.php?edit=<?=$s['id']?>">Sửa</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
